// ---- Saved threat level ----
const level=String(ca.overall_threat_level||'LOW').toUpperCase();
const active=level==='MEDIUM'||level==='HIGH'||level==='CRITICAL';

// ---- Threat-type detection from the saved assessment (deterministic, no LLM) ----
const haystack=[Array.isArray(ca.threats)?ca.threats.join(' '):'',Array.isArray(ca.evidence)?ca.evidence.join(' '):'',ca.regional_summary||''].join(' ').toLowerCase();
const types={
  rain:/flood|rain|precipitation|waterlog|inundat|monsoon/.test(haystack),
  wind:/wind|gust|storm|cyclone|gale/.test(haystack),
  heat:/heat|humid|temperature|hot|feels-like|feels like|heat index/.test(haystack),
  fire:/fire|wildfire|smoke|burn/.test(haystack),
  cold:/cold|snow|frost|freeze|freezing/.test(haystack),
  disaster:/earthquake|tsunami|volcan|landslide|disaster alert|gdacs/.test(haystack),
};

// ---- Evidence-based escalation: urgent actions ONLY when the saved evidence confirms a
//      specific serious hazard. Never inferred from precipitation probability alone. ----
const caStr=JSON.stringify(ca||{});
// Severe rainfall amount / accumulation / official warning (same signal the wording scrub uses)
const hasRainEvidence=/\d+(?:\.\d+)?\s*mm|rainfall of|accumulat|red alert|orange alert|official warning|severe weather warning|flood warning/i.test(caStr);
const confirmedFlooding=/flood warning|flash flood|floodwater|inundation|flooding is (?:occurring|underway|reported|confirmed)|active flooding|ongoing flood/i.test(caStr);
const officialEvacuation=/evacuat/i.test(caStr);
const activeWildfire=/active (?:wild)?fire|wildfire (?:is )?(?:active|spreading|burning)|actively burning|fire detected|fire is spreading|hotspot detected/i.test(caStr);
// Dangerous wind: numeric gust >= 75 km/h, or explicit severe-wind wording. Probability text ignored.
let maxGust=0; const gm=caStr.match(/(\d+(?:\.\d+)?)\s*km\/h/gi)||[]; for(const g of gm){ const n=parseFloat(g); if(!isNaN(n)&&n>maxGust)maxGust=n; }
const dangerousWind=maxGust>=75||/damaging wind|destructive wind|gale warning|storm warning|hurricane|cyclone warning/i.test(caStr);
const escalate=hasRainEvidence||confirmedFlooding||officialEvacuation||activeWildfire||dangerousWind;

const baseLevel=(level==='HIGH'||level==='CRITICAL')?'HIGH':(level==='MEDIUM'?'MEDIUM':'LOW');
const effectiveLevel=escalate?'HIGH':baseLevel;

// ---- Level-aware templates: stakeholder -> level -> (type map for MEDIUM/HIGH) ----
// LOW  = monitor and prepare (low-impact only; no evacuation / relocation / emergency deployment)
// MEDIUM = take precautions (drainage, protect assets, relocate vulnerable items only if likely)
// HIGH = act immediately (move people/livestock/assets, suspend operations, evacuate, reroute)
const T={
