const stakeObj=T[stakeholder]||T.general_public;
const order=['rain','wind','heat','fire','cold','disaster'];

// ---- Prioritize the highest-risk threat type ----
// Score each detected threat type by the highest severity of the saved threats
// that reference it, so the most serious threat's actions are listed first while
// still including every saved threat type.
const typePatterns={
  rain:/flood|rain|precipitation|waterlog|inundat|monsoon/i,
  wind:/wind|gust|storm|cyclone|gale/i,
  heat:/heat|humid|temperature|hot|feels[- ]?like|heat index|arid|dry/i,
  fire:/fire|wildfire|smoke|burn/i,
  cold:/cold|snow|frost|freeze|freezing/i,
  disaster:/earthquake|tsunami|volcan|landslide|disaster alert|gdacs/i,
};
function sevRank(s){ const v=String(s||'').toUpperCase(); if(v==='CRITICAL')return 4; if(v==='HIGH')return 3; if(v==='MEDIUM')return 2; if(v==='LOW')return 1; return 0; }
function threatBlob(x){ if(x&&typeof x==='object')return [x.type,x.description,x.short_finding,x.detail,x.title].filter(Boolean).join(' '); return String(x||''); }
const savedThreats=Array.isArray(ca.threats)?ca.threats:[];
const savedEvidence=Array.isArray(ca.evidence)?ca.evidence:[];
// Priority ranking: the OSINT agent lists threats in priority order, so an
// earlier position = higher priority. When explicit per-threat severity exists,
// it takes precedence. typeScore holds the highest severity seen (0 if none);
// typePos holds the earliest threat-array index a type appears at (lower = more
// important). Evidence order is used as a secondary position signal.
const typeScore={}; const typePos={};
for(const k of order){ typeScore[k]=types[k]?0:0; if(types[k])typePos[k]=999; }
function scan(list,base){ for(let i=0;i<list.length;i++){ const blob=threatBlob(list[i]); const rank=sevRank(list[i]&&list[i].severity); for(const k of order){ if(typePatterns[k].test(blob)){ types[k]=true; if(rank>(typeScore[k]||0))typeScore[k]=rank; const pos=base+i; if(typePos[k]===undefined||pos<typePos[k])typePos[k]=pos; } } } }
scan(savedThreats,0);
scan(savedEvidence,100);
// Detected types ordered by: explicit severity desc, then earliest position asc,
// then canonical order. This surfaces the dominant threat's actions first
// (e.g. heat listed first by OSINT) while still including every saved type.
const detectedOrder=order.filter((k)=>types[k]).sort((a,b)=>{
  const ds=(typeScore[b]||0)-(typeScore[a]||0); if(ds!==0)return ds;
  const dp=(typePos[a]===undefined?999:typePos[a])-(typePos[b]===undefined?999:typePos[b]); if(dp!==0)return dp;
  return order.indexOf(a)-order.indexOf(b);
});

// Highest saved threat-type severity (0..4). Lets a dominant hazard (e.g. HIGH
// "extreme heat" threat) drive type-specific precautions even when the OVERALL
// level is LOW — so farmer heat advice appears when heat is the main threat.
let maxTypeSev=0; for(const k of detectedOrder){ const sc=(typeScore[k]||0); if(sc>maxTypeSev)maxTypeSev=sc; }
// Template tier: escalation/HIGH -> high; otherwise use the highest of the overall
// level and the dominant threat-type severity (MEDIUM+ threat => precaution tier).
let tier;
if(effectiveLevel==='HIGH'){ tier='high'; }
else if(effectiveLevel==='MEDIUM'||maxTypeSev>=2){ tier='medium'; }
else { tier='low'; }

// Build candidate step pool matched to the tier, highest-risk threat first.
let pool=[];
if(tier==='low'){
  pool=(stakeObj.low||[]).slice();
} else {
  const tierMap=(tier==='high'?stakeObj.high:stakeObj.medium)||{};
  if(detectedOrder.length){ for(const t of detectedOrder){ if(Array.isArray(tierMap[t])) pool=pool.concat(tierMap[t]); } }
  if(pool.length<3&&Array.isArray(tierMap.generic)) pool=pool.concat(tierMap.generic);
